mapper.select:
SELECT COUNT(*)
FROM report
WHERE status = #{status}

  AND reason = #{reason}

SELECT r.id AS reportId, r.post_id AS postId, p.title AS postTitle, r.reason AS reason, r.weight AS weight, r.status AS status, r.is_false_report AS isFalseReport, p.risk_score AS riskScore, r.created_at AS createdAt FROM report r JOIN post p ON p.id = r.post_id WHERE r.status = #{status}
AND r.reason = #{reason}
ORDER BY p.risk_score DESC, r.created_at ASC, r.id ASC LIMIT #{limit} OFFSET #{offset}
